beforeExample:
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class MyClass {
    public void foo(String[] items) {
        List<String> list = new ArrayList<String>(Arrays.asList(items));
        System.out.println(list);
    }
}

afterExample:
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class MyClass {
    public void foo(String[] items) {
        List<String> list = new ArrayList<>(Arrays.asList(items));
        System.out.println(list);
    }
}

negativeExample:
import java.util.LinkedList;
import java.util.List;
import java.util.Set;
import java.util.HashSet;
import java.util.ArrayList;

public class MyClass {
    public void bar() {
        List<String> list = new LinkedList<String>(); // Different collection type
        Set<String> set = new HashSet<String>(); // Different collection type
        List<String> anotherList = new ArrayList<String>(); // Not initialized from Arrays.asList
        ArrayList<String> justList = new ArrayList<String>(); // Not initialized from Arrays.asList
    }
}
